# Chaque entrée contient deux leçons distinctes, puis trois problèmes corrigés.
_TEXTS = {
 'laplace_initiales': (
  ('Une sortie garde la trace de son état initial','Sup · Physique',
   '<p>La sortie <b>y</b> vérifie τ dy/dt+y=KE après l’application d’une tension constante E. Le gain K et la constante de temps τ sont fixés. À t=0, la sortie vaut y₀.</p><p>La solution est y(t)=KE+(y₀−KE)e<sup>−t/τ</sup>. Elle respecte y(0)=y₀ et tend vers KE. Le terme y₀e<sup>−t/τ</sup> décrit la réponse libre ; KE(1−e<sup>−t/τ</sup>) décrit la réponse à l’entrée, au repos initial.</p>'),
  ('Un transfert suppose un état initial nul','Spé · SI / au-delà · Mathématiques',
   '<p>On note p la variable de Laplace et Y(p) la transformée unilatérale de y(t). La dérivée devient pY(p)−y₀. Il vient (1+τp)Y(p)=KE/p+τy₀.</p><p>Le transfert H(p)=K/(1+τp) relie entrée et sortie quand y₀=0. Il ne contient pas à lui seul la réponse due à un état initial chargé. En SI, on utilise les réponses canoniques ; le calcul d’inversion générale est un prolongement mathématique.</p>'),
  [('Retrouver une valeur à une constante de temps','Sup','Prendre K=2, E=1 V, y₀=0 et τ=1 s. Calculer y(τ) et y(∞).','La valeur finale est KE=2 V. À t=τ, y=2(1−e⁻¹)≈1,264 V, soit 63,2 % de la variation totale.'),
   ('Démarrer au-dessus de l’équilibre','Sup','Prendre K=2, E=1 V et y₀=3 V. La sortie dépasse-t-elle son état initial ?','y(t)=2+e⁻ᵗ/τ V. Elle décroît de 3 V vers 2 V sans dépasser 3 V. La dérivée initiale vaut (KE−y₀)/τ=−1/τ V/s.'),
   ('Retrouver le terme initial en Laplace','Au-delà · Mathématiques','Pour τ=2 s, K=3, E=1 V et y₀=−1 V, écrire Y(p). Pourquoi Y(p)≠H(p)E/p ?','(1+2p)Y=3/p−2, donc Y=(3/p−2)/(1+2p). Le terme −2/(1+2p) est la contribution de l’état initial ; H(p)E/p ne décrit que le départ au repos.')]),
 'bode_second_ordre': (
  ('Passer de la forme canonique au diagramme de Bode','Sup / Spé · Physique et SI',
   '<p>Le transfert est H(p)=Kω₀²/(p²+2ζω₀p+ω₀²). K est le gain statique, ω₀ la pulsation propre et ζ l’amortissement. En régime sinusoïdal, on pose p=jω, où j²=−1.</p><p>Le module est K/√[(1−(ω/ω₀)²)²+4ζ²(ω/ω₀)²]. Le gain en dB vaut 20 log₁₀|H|. La phase doit tenir compte du quadrant du dénominateur ; elle passe de 0° à −180°. À haute fréquence, la pente tend vers −40 dB par décade.</p>'),
  ('Distinguer résonance et dépassement','Spé · SI',
   '<p>Une résonance apparaît pour ζ&lt;1/√2 ; sa pulsation vaut ωᵣ=ω₀√(1−2ζ²). Le pic disparaît avant que les oscillations temporelles disparaissent.</p><p>Après un échelon unité et un départ au repos, le dépassement relatif vaut exp[−πζ/√(1−ζ²)] pour ζ&lt;1. Pour ζ≥1, la réponse est monotone. Les formules temporelles sont fournies : leur inversion de Laplace n’est pas exigée en SI.</p>'),
  [('Lire le gain à la pulsation propre','Sup','Prendre K=1, ζ=0,5. Calculer H(jω₀), son module et sa phase.','À ω=ω₀, le dénominateur réduit vaut 2jζ=j. Donc H=1/j=−j, |H|=1 et la phase vaut −90°. Le gain est 0 dB.'),
   ('Un dépassement sans pic de résonance','Spé · SI','Le système a ζ=0,8. Y a-t-il un pic de résonance ? Quel est le dépassement après un échelon ?','0,8>1/√2 : aucun pic de résonance. Mais 0,8<1 : le dépassement vaut 100 exp(−π·0,8/0,6)≈1,52 %. Les deux seuils diffèrent.'),
   ('Comparer deux décades à haute fréquence','Sup','Très au-dessus de ω₀, on multiplie ω par 100. Quelle variation de gain prévoir ?','|H|≈K(ω₀/ω)². Multiplier ω par 100 divise le module par 10⁴ ; le gain varie de −80 dB. Cela correspond à deux décades de pente −40 dB/décade.')]),
 'retroaction_sensibilite': (
  ('Réduire un retour négatif','Sup / Spé · SI',
   '<p>L’entrée est e, la sortie s, le gain direct μ et le gain du capteur β. L’erreur vaut ε=e−βs et la chaîne directe donne s=με au régime permanent.</p><p>En remplaçant ε, on obtient s(1+μβ)=μe, puis G=s/e=μ/(1+μβ). Le produit μβ est le gain de boucle statique. Pour μβ grand, G se rapproche de 1/β, à condition que β reste fixé.</p>'),
  ('Comparer sensibilité locale et variation finie','Au-delà · SI',
   '<p>La sensibilité relative à μ est Sμ=(μ/G)dG/dμ=1/(1+μβ). Une petite variation dμ produit dG/G=Sμ dμ/μ.</p><p>Pour une variation finie δ, utiliser μ₂=μ(1+δ), puis recalculer G₂ exactement. Une variation de 50 % n’est pas automatiquement petite. Le retour protège surtout contre les variations de la chaîne directe ; une erreur du capteur β affecte aussi la valeur finale.</p>'),
  [('Calculer un gain fermé','Sup · SI','μ=20 et β=0,1. Calculer G et la sensibilité Sμ.','μβ=2. G=20/3≈6,667 et Sμ=1/3. Une petite variation relative de μ est divisée approximativement par 3 sur G.'),
   ('Vérifier une variation de 20 %','Spé · SI','Avec μ=20 et β=0,1, augmenter μ de 20 %. Comparer la variation exacte de G à l’approximation locale.','μ₂=24 et G₂=24/3,4≈7,059. La hausse exacte est (G₂/G−1)≈5,882 %. L’approximation locale donne 20/3≈6,667 % ; elle surestime ici la variation.'),
   ('Supprimer le capteur','Sup · SI','Que deviennent G, Sμ et la constante de temps fermée si β=0 ?','G=μ, Sμ=1 et la constante de temps reste τ. Le système ne bénéficie plus du retour ; une variation relative de μ se transmet intégralement au gain.')]),
 'moteur_x': (
  ('Le TP en boucle ouverte','Sup · SI',
   '<p>Un amplificateur de gain μ précède le moteur X de transfert K₀/(1+τp). K₀ s’exprime en rad·s⁻¹/V et τ en secondes. Le transfert tension-vitesse est T(p)=μK₀/(1+τp).</p><p>À partir du repos, une tension E appliquée en échelon donne Ω(t)=μK₀E(1−e<sup>−t/τ</sup>). La vitesse permanente est μK₀E et 63,2 % de cette vitesse est atteint à t=τ.</p>'),
  ('Fermer le retour du TP','Spé · SI',
   '<p>Le capteur convertit Ω′ en tension βΩ′. L’erreur appliquée à l’amplificateur vaut ε=E−βΩ′. En éliminant ε, on obtient T′(p)=μK₀/(1+μβK₀+τp).</p><p>La forme canonique donne T₀′=μK₀/(1+μβK₀) et τ′=τ/(1+μβK₀). Le retour raccourcit le transitoire et réduit le gain au même E. Pour demander une vitesse précise, la consigne et l’étalonnage du capteur doivent être interprétés ensemble.</p>'),
  [('Retrouver les réglages initiaux','Sup · SI','Prendre E=5 V, μ=2, K₀=2 rad·s⁻¹/V, τ=1 s et β=0,5 V/(rad/s). Calculer les deux vitesses finales.','T₀=4 rad·s⁻¹/V ; Ω∞=20 rad/s. Le facteur fermé vaut 1+μβK₀=3 ; T₀′=4/3 et Ω′∞=20/3≈6,667 rad/s. τ′=1/3 s.'),
   ('Comparer les pentes au départ','Spé · SI','Au départ au repos, les pentes de Ω et Ω′ sont-elles différentes ? Justifier.','Ω̇(0)=T₀E/τ. Pour la boucle fermée, Ω̇′(0)=T₀′E/τ′=T₀E/τ. Les pentes initiales sont égales : au tout premier instant, le capteur renvoie une vitesse nulle.'),
   ('Interpréter un retour très fort','Spé · SI','Lorsque μβK₀ devient très grand, vers quelle valeur tend Ω′∞ ? Quelle limite réelle manque au modèle ?','Ω′∞=μK₀E/(1+μβK₀) tend vers E/β. La constante de temps tend vers zéro dans le modèle idéal. Les retards, l’inductance et la saturation limitent cette accélération dans un moteur réel.')]),
 'moteur_mcc': (
  ('Deux bilans couplés','Sup / Spé · SI',
   '<p>La tension U alimente un induit de résistance R et d’inductance L. Le courant i crée le couple ki. La vitesse Ω crée la force contre-électromotrice kΩ. Les constantes ont la même valeur numérique en unités SI.</p><p>Les équations sont L di/dt=U−Ri−kΩ et J dΩ/dt=ki−bΩ−Cᵣ. L’inertie J, le frottement visqueux b et le couple résistant Cᵣ définissent la charge. Le courant et la vitesse se déterminent ensemble.</p><p>La durée électrique L/R peut être bien plus courte que le démarrage mécanique. La vue courte du courant résout cette montée ; elle la compare au courant (U/R)(1−exp(−Rt/L)) d’un rotor maintenu immobile, où t est le temps en secondes.</p>'),
  ('Vérifier l’équilibre et la puissance','Spé · SI',
   '<p>Au régime permanent, les dérivées sont nulles. On obtient Ω∞=(kU−RCᵣ)/(Rb+k²), puis i∞=(U−kΩ∞)/R. Une charge accrue réduit la vitesse et augmente le courant.</p><p>La puissance électrique Ui se répartit entre pertes Joule Ri², variation d’énergie magnétique et puissance convertie kiΩ. Côté mécanique, cette dernière alimente la variation d’énergie cinétique, le frottement bΩ² et la charge CᵣΩ. Le modèle signé ne comporte pas de frottement sec.</p>'),
  [('Calculer un fonctionnement à vide','Spé · SI','U=12 V, R=2 Ω, k=0,1, b=0,01 N·m·s et Cᵣ=0. Calculer Ω∞ et i∞.','Rb+k²=0,03. Ω∞=1,2/0,03=40 rad/s ; i∞=(12−4)/2=4 A. Le couple moteur 0,4 N·m équilibre le frottement 0,01×40=0,4 N·m.'),
   ('Ajouter une charge de 0,03 N·m','Spé · SI','Reprendre les valeurs précédentes avec Cᵣ=0,03 N·m. Calculer vitesse, courant et pertes Joule permanentes.','Ω∞=(1,2−0,06)/0,03=38 rad/s ; i∞=(12−3,8)/2=4,1 A. Les pertes Joule valent Ri∞²=2×4,1²=33,62 W. Le couple moteur vaut 0,41 N·m, égal à 0,38+0,03.'),
   ('Interpréter les pentes initiales','Sup · SI','Le moteur part de i=0 et Ω=0. Quelles sont les dérivées initiales si une charge constante Cᵣ est déjà appliquée ?','i̇(0)=U/L et Ω̇(0)=−Cᵣ/J. À vide, la pente initiale mécanique est nulle. Avec la charge signée appliquée dès le départ, le modèle peut d’abord tourner légèrement dans le sens négatif ; aucune butée n’est prévue.')]),
 'correcteur_pi': (
  ('Ajouter une action intégrale','Spé · SI',
   '<p>La consigne r et la sortie y définissent l’erreur e=r−y. Un PI demande u=Kₚe+v, où dv/dt=(Kₚ/Tᵢ)e. L’action proportionnelle répond immédiatement ; l’action intégrale accumule l’écart.</p><p>Si l’équilibre est accessible et le PI actif, dv/dt=0 impose e=0. Une intégrale ne crée pas une commande disponible sans limite : pour un procédé de gain K et une limite uₘₐₓ, il faut |r|≤Kuₘₐₓ.</p>'),
  ('Que se passe-t-il pendant une saturation ?','Au-delà · SI',
   '<p>La commande appliquée u est limitée, alors que Kₚe+v peut continuer de croître. Tant que l’erreur conserve son signe, v s’accumule ; la sortie peut tarder à revenir après la baisse de consigne.</p><p>La correction proposée ajoute [u−(Kₚe+v)]/Tᵢ à dv/dt. Elle ramène l’intégrale vers une valeur compatible avec l’actionneur. Cette correction de saturation est un prolongement ; elle ne remplace pas le réglage de stabilité du PI.</p>'),
  [('Comparer P et PI au régime permanent','Spé · SI','Sans saturation, un procédé a K=1 et un correcteur proportionnel Kₚ=2. Pour r=1, calculer l’erreur finale. Que change un PI stable et actif ?','Avec P, y∞=KKₚr/(1+KKₚ)=2/3 et e∞=1/3. Avec un PI stable dont l’intégrale est active, e∞=0 et y∞=1, si la commande nécessaire est accessible.'),
   ('Tester l’accessibilité','Spé · SI','K=1, uₘₐₓ=0,5 et r=3. Une intégrale peut-elle annuler l’erreur constante ?','Non. La sortie permanente accessible est au plus Kuₘₐₓ=0,5. L’erreur reste au moins 2,5. Sans correction, v continue de croître : le manque de commande ne se résout pas par l’accumulation intégrale.'),
   ('Comparer deux équilibres de l’intégrale','Au-delà · SI','Pendant une saturation haute, u=uₘₐₓ. Écrire la condition dv/dt=0 pour la correction proposée.','0=(Kₚ/Tᵢ)e+[uₘₐₓ−Kₚe−v]/Tᵢ, donc v=uₘₐₓ. L’intégrale reste bornée à cet équilibre. Sans correction, dv/dt=(Kₚ/Tᵢ)e reste positif si e>0.')]),
 'stabilite_marges': (
  ('Lire deux distances à une limite','Spé · SI',
   '<p>La boucle ouverte vaut L(p)=K/[(1+τ₁p)(1+τ₂p)(1+τ₃p)]. À la pulsation ωc où |L|=1, la marge de phase est 180°+arg L(jωc). À la pulsation ωπ où la phase est −180°, la marge de gain en dB vaut −20 log₁₀|L(jωπ)|.</p><p>Si K≤1, le gain n’atteint pas 0 dB à une pulsation strictement positive : la marge de phase n’a pas de croisement de référence. Il faut afficher cette absence plutôt qu’une valeur artificielle.</p>'),
  ('Comparer aux pôles fermés','Spé · SI / au-delà · Mathématiques',
   '<p>Avec un retour négatif unitaire, le transfert fermé est L/(1+L). Ses pôles vérifient (1+τ₁p)(1+τ₂p)(1+τ₃p)+K=0. Un pôle à partie réelle positive entraîne une croissance temporelle.</p><p>Pour trois constantes égales τ, la limite se produit à K=8 et ωπ=√3/τ. Ce cas permet de vérifier les marges sans faire appel aux critères de Routh ou de Nyquist, qui ne sont pas au programme SI.</p>'),
  [('Retrouver la limite pour trois constantes égales','Spé · SI','Prendre τ₁=τ₂=τ₃=τ. À quelle pulsation la phase atteint-elle −180° ? Quel gain K donne alors |L|=1 ?','La phase est −3 arctan(ωτ). Il faut arctan(ωτ)=60°, donc ωτ=√3. Chaque facteur a pour module 2 ; |L|=K/8. Le gain limite est K=8.'),
   ('Calculer une marge de gain','Spé · SI','Pour trois constantes égales et K=4, calculer la marge de gain.','À ωπ=√3/τ, |L|=4/8=0,5. La marge de gain vaut −20 log₁₀(0,5)=20 log₁₀2≈6,02 dB. Doubler K atteint la limite.'),
   ('Interpréter un gain inférieur à 1','Spé · SI','K=0,5 et les trois constantes de temps sont positives. Pourquoi le logiciel n’affiche-t-il pas une marge de phase numérique ?','Le module de L vaut K au continu et décroît avec ω. Il reste donc inférieur à 1 partout : aucun croisement à 0 dB n’existe. L’absence de marge de phase numérique ne signifie pas que la boucle est instable.')]),
 'isolation_sismique': (
  ('Lire le capteur et le signe de la force','Spé · SI · P17',
   '<p>Le déplacement du sol est x₀, celui de la masse x. La plante vérifie x=I(x₀−αF), où I(p)=ωᵣ²/(p²+ωᵣ²). Le capteur mesure <b>x−x₀</b> et l’actionneur dérivateur donne F=ηp(x−x₀).</p><p>En remplaçant F puis en regroupant x, on obtient G(p)=x/x₀=(ωᵣ²+cp)/(p²+cp+ωᵣ²), avec c=αηωᵣ². Le retour est aussi une anticipation du mouvement du sol : le terme cp apparaît au numérateur.</p>'),
  ('Amortir une résonance ne filtre pas tout','Sup · Physique / spé · SI',
   '<p>Le dénominateur est celui d’un second ordre d’amortissement ζ=c/(2ωᵣ). Pour η&gt;0, le modèle est amorti. Sans contrôle, η=0 : la résonance exacte n’a pas de régime périodique borné.</p><p>À haute pulsation, le transfert sans contrôle décroît comme ωᵣ²/ω². Avec le dérivateur idéal, il décroît comme c/ω. Le contrôle atténue la résonance mais peut transmettre davantage le mouvement rapide. Les courbes temporelles incluent le départ au repos.</p>'),
  [('Reconstituer le transfert contrôlé','Spé · SI','Partir de x=I(x₀−αF), F=ηp(x−x₀) et I=ωᵣ²/(p²+ωᵣ²). Déterminer x/x₀.','x(1+αηpI)=Ix₀(1+αηp). Donc G=I(1+αηp)/(1+αηpI)=(ωᵣ²+αηωᵣ²p)/(p²+αηωᵣ²p+ωᵣ²). Le numérateur est du premier degré.'),
   ('Choisir un amortissement critique','Spé · SI','ωᵣ=8 rad/s et α=0,01 m/N. Déterminer η pour ζ=1.','ζ=αηωᵣ/2. Donc η=2/(αωᵣ)=25 N·s/m. Le dénominateur devient (p+8)². Le transfert garde le numérateur 64+16p ; il n’est pas un simple passe-bas à numérateur constant.'),
   ('Contrôler la cohérence mécanique','Sup · Physique','On définit α=l²/(C−Mgl) et ωᵣ²=(C−Mgl)/(Ml²). Calculer αωᵣ² et en déduire M pour α=0,01 m/N et ωᵣ=8 rad/s.','Les facteurs l² et C−Mgl se simplifient : αωᵣ²=1/M. M=1/(0,01×64)=1,5625 kg. Les deux paramètres ne représentent pas une masse arbitraire indépendante.')]),
 'echantillonnage_adc': (
  ('Pourquoi les échantillons peuvent tromper','Spé · Physique PT/PSI',
   '<p>Un signal est mesuré à tₖ=k/fₑ. Pour toute fréquence f, ajouter un multiple entier de fₑ conserve la phase à ces instants. Le signal continu d’origine n’est donc pas déterminé par les seules valeurs sans hypothèse de bande limitée.</p><p>Pour éviter le repliement d’un signal de fréquence maximale fₘₐₓ, on impose fₑ&gt;2fₘₐₓ et on limite réellement la bande avant l’acquisition. Un filtre antirepliement est nécessaire si des composantes plus rapides sont présentes.</p>'),
  ('Coder une tension sur un nombre fini de niveaux','Spé · Physique PT/PSI',
   '<p>Un convertisseur de N bits possède 2ᴺ codes. Pour la plage [−Vₘₐₓ,+Vₘₐₓ], le modèle utilisé a un pas q=2Vₘₐₓ/2ᴺ. Chaque code représente le centre d’un intervalle ; hors saturation, l’erreur reste dans [−q/2,+q/2].</p><p>Augmenter N réduit le pas ; cela ne corrige pas une acquisition repliée. L’approximation d’une erreur uniforme donne une valeur RMS q/√12, mais une série déterministe d’échantillons ne suit pas toujours ce modèle statistique.</p>'),
  [('Retrouver une fréquence repliée','Spé · Physique','Un signal de 800 Hz est échantillonné à 1000 Hz. Quelle fréquence apparaît dans la bande [0,500 Hz] ?','800−1000=−200 Hz. Le module de la fréquence ramenée est 200 Hz. Le signe et la phase doivent être conservés pour reproduire exactement les échantillons.'),
   ('Calculer le pas et l’erreur maximale','Spé · Physique','Un CAN bipolaire de 8 bits couvre −2 à +2 V. Calculer q et l’erreur maximale hors saturation du modèle à centres d’intervalles.','q=4/256=0,015625 V, soit 15,625 mV. L’erreur maximale est q/2=7,8125 mV. La valeur +2 V est représentée par le centre du dernier intervalle, donc légèrement en dessous de +2 V.'),
   ('Distinguer deux défauts','Spé · Physique','On mesure une sinusoïde de 1 kHz et d’amplitude 3 V avec fₑ=1500 Hz et une plage ±1 V. Doubler N résout-il les deux problèmes ?','Non. fₑ<2f donne un repliement ; l’amplitude dépasse ±1 V et fait saturer les codes. Doubler N affine les intervalles dans la plage, sans augmenter fₑ ni la plage de tension.')]),
 'filtre_rif': (
  ('Une somme de valeurs retardées','Spé · Physique PT/PSI',
   '<p>Le filtre calcule yₖ=(xₖ+xₖ₋₁+…+xₖ₋ₙ₊₁)/N. Les valeurs antérieures au début sont nulles. Une impulsion x₀=1 puis 0 donne hₖ=1/N pendant N termes, puis hₖ=0.</p><p>La réponse impulsionnelle est finie : le filtre est RIF. Pour une entrée constante, la somme des coefficients vaut 1, donc le signal constant est conservé après le remplissage de la mémoire.</p>'),
  ('Choisir la fenêtre selon la fréquence','Au-delà · Traitement du signal',
   '<p>On note z la variable du temps discret et z⁻¹ un retard. H(z)=(1/N)Σⱼ₌₀ᴺ⁻¹z⁻ʲ. Sur le cercle unité, z=e<sup>j2πf/fₑ</sup> ; des annulations apparaissent pour f=m fₑ/N, hors f=0.</p><p>Les coefficients symétriques donnent un retard de groupe (N−1)Tₑ/2 hors les zéros. Agrandir la fenêtre ne conserve pas toutes les fréquences utiles : il faut comparer leur gain avec celui du bruit.</p>'),
  [('Écrire une réponse impulsionnelle','Spé · Physique','Pour N=4 et une mémoire vide, donner les six premiers termes de la réponse à x₀=1 puis 0.','h₀=h₁=h₂=h₃=1/4, puis h₄=h₅=0. La somme vaut 1 et la réponse est finie ; aucune sortie précédente n’est réinjectée.'),
   ('Annuler une fréquence de bruit','Spé · Physique','fₑ=1000 Hz et N=10. Le bruit est une sinusoïde de 300 Hz. Pourquoi est-il annulé après le transitoire ?','300=3 fₑ/N. Sur dix échantillons, les phases parcourent trois tours complets et leur somme complexe est nulle. Le filtre annule cette raie, sous réserve de stabilité de sa fréquence.'),
   ('Calculer le retard','Au-delà · Traitement du signal','N=9 et fₑ=1000 Hz. Quel retard de groupe possède la moyenne glissante ? Une entrée constante est-elle atténuée ?','Le retard vaut (9−1)/(2×1000)=4 ms. Le gain au continu vaut la somme des neuf coefficients, donc 1 : une constante n’est pas atténuée après le transitoire de remplissage.')]),
 'filtre_rii_z': (
  ('Une suite géométrique dans un filtre','Sup · Mathématiques / spé · Physique',
   '<p>La récurrence est yₖ=a yₖ₋₁+(1−a)xₖ, avec y₋₁=0. L’impulsion discrète x₀=1 puis 0 produit hₖ=(1−a)aᵏ. La sortie d’un échelon xₖ=1 vaut 1−a<sup>k+1</sup>.</p><p>Si 0&lt;a&lt;1, la mémoire décroît sans alternance. Si −1&lt;a&lt;0, elle alterne ; le filtre ne se comporte plus comme le même passe-bas lent. Pour a=0, yₖ=xₖ : la mémoire disparaît.</p>'),
  ('Un pôle et un critère de stabilité','Au-delà · Temps discret',
   '<p>Avec une mémoire initiale vide, H(z)=(1−a)/(1−az⁻¹)=(1−a)z/(z−a). Le pôle est a, sauf si a=0 où il se simplifie. La somme Σ|hₖ| vaut |1−a|/(1−|a|) pour |a|&lt;1.</p><p>Cette somme finie garantit qu’une entrée bornée produit une sortie bornée. Une réponse qui décroît lentement peut être stable. Il faut distinguer une grande durée de mémoire d’un pôle situé sur ou hors du cercle unité.</p>'),
  [('Retrouver l’impulsion','Sup · Mathématiques','Pour a=0,8, calculer h₀, h₁ et h₂. Quelle est la somme de tous les hₖ ?','h₀=0,2 ; h₁=0,16 ; h₂=0,128. La série géométrique donne Σhₖ=0,2/(1−0,8)=1. Le gain au continu vaut donc 1.'),
   ('Observer un retour négatif discret','Au-delà · Temps discret','Pour a=−0,8, calculer les trois premiers termes de h et le gain à la fréquence de Nyquist.','h₀=1,8 ; h₁=−1,44 ; h₂=1,152. À f/fₑ=1/2, z⁻¹=−1 et H=(1−a)/(1+a)=1,8/0,2=9. Le filtre favorise la fréquence haute tout en restant stable.'),
   ('Mesurer la durée de mémoire','Sup · Mathématiques','Pour 0<a<1, au bout de combien d’échantillons le facteur aᵏ atteint-il e⁻¹ ? Calculer pour a=0,98.','aᵏ=e⁻¹ donne k=−1/ln(a). Pour a=0,98, k≈49,5 échantillons. La durée réelle vaut ce nombre multiplié par Tₑ ; sans fréquence d’échantillonnage, on ne peut pas la donner en secondes.')]),
 'discretisation': (
  ('Retrouver Euler implicite dans P17','Spé · Physique / au-delà · Temps discret',
   '<p>Le filtre analogique vérifie τ dy/dt+y=x. La différence arrière (yₖ−yₖ₋₁)/Tₑ donne yₖ=a yₖ₋₁+b xₖ, avec a=τ/(τ+Tₑ) et b=Tₑ/(τ+Tₑ).</p><p>Pour τ=1 ms et Tₑ=50 µs, a=20/21 et b=1/21. Le cas y₀=1, x₁=1 puis 0 donne y₁=1, puis yₖ=(20/21)<sup>k−1</sup> pour k≥1. La réponse impulsionnelle à état initial nul donne au contraire y₁=1/21.</p>'),
  ('Comparer trapèzes et maintien exact','Au-delà · Temps discret',
   '<p>La règle des trapèzes conduit à yₖ=aB yₖ₋₁+bB(xₖ+xₖ₋₁), où aB=(2τ−Tₑ)/(2τ+Tₑ) et bB=Tₑ/(2τ+Tₑ). Le transfert bilinéaire contient donc <b>1+z⁻¹</b> au numérateur.</p><p>Une entrée constante sur ]tₖ₋₁,tₖ] donne exactement yₖ=e<sup>−Tₑ/τ</sup>yₖ₋₁+(1−e<sup>−Tₑ/τ</sup>)xₖ. Les indices fixent la présence d’un retard dans un transfert ZOH : une entrée indexée par la borne gauche agit au pas suivant. La comparaison affiche la convention utilisée.</p>'),
  [('Distinguer l’état initial de l’impulsion','Spé · Physique','τ=1 ms et Tₑ=50 µs. Pour Euler implicite, calculer y₁ et y₂ si x₁=1 puis 0, d’abord avec y₀=1, puis avec y₀=0.','Avec y₀=1 : y₁=20/21+1/21=1 ; y₂=20/21. Avec y₀=0 : y₁=1/21 ; y₂=20/441. Une entrée identique donne des sorties différentes à cause de l’état initial.'),
   ('Trouver le bon numérateur bilinéaire','Au-delà · Temps discret','Dans H(p)=1/(1+τp), remplacer p par (2/Tₑ)(1−z⁻¹)/(1+z⁻¹). Déterminer H(z).','Après multiplication par 1+z⁻¹, H(z)=(1+z⁻¹)/[(1+2τ/Tₑ)+(1−2τ/Tₑ)z⁻¹]. La récurrence devient (1+2τ/Tₑ)yₖ+(1−2τ/Tₑ)yₖ₋₁=xₖ+xₖ₋₁.'),
   ('Vérifier les pôles pour un grand pas','Au-delà · Temps discret','Prendre Tₑ=3τ. Calculer les pôles Euler, bilinéaire et ZOH. Les trois méthodes proposées restent-elles stables ?','Euler : a=1/4. Bilinéaire : aB=(2−3)/(2+3)=−1/5. ZOH : aZ=e⁻³≈0,0498. Leurs modules sont inférieurs à 1 : elles restent stables. Le pôle bilinéaire négatif donne une alternance artificielle pour un pas aussi grand.')]),
 'polezero_z': (
  ('Deux pôles conjugués dans le plan z','Au-delà · Temps discret',
   '<p>Les pôles sont r e<sup>±jθ</sup>, où r est leur module et θ leur angle en radians. Leur polynôme est z²−2r cos(θ)z+r². La récurrence homogène produit des oscillations de fréquence relative θ/(2π), dont l’enveloppe décroît comme rᵏ.</p><p>Le critère |r|&lt;1 assure la décroissance. Il concerne le module dans le plan z ; en temps continu, on utilise au contraire la partie réelle du pôle. Les deux critères ne se lisent pas sur le même axe.</p>'),
  ('Mettre un creux à une fréquence choisie','Au-delà · Traitement du signal',
   '<p>Deux zéros e<sup>±jψ</sup> sur le cercle unité donnent le numérateur c(1−2cos(ψ)z⁻¹+z⁻²). Sur z=e<sup>j2πf/fₑ</sup>, le gain s’annule pour f/fₑ=ψ/(2π).</p><p>Le facteur c normalise le gain continu à 1. Le creux est exact à la fréquence choisie ; une raie voisine n’est pas nécessairement fortement atténuée. Des pôles proches de la même direction peuvent rendre le voisinage plus sélectif.</p>'),
  [('Convertir un angle en fréquence','Sup · Mathématiques / au-delà','Les pôles ont θ=60° et la fréquence d’échantillonnage vaut 1200 Hz. Quelle fréquence d’oscillation représentent-ils ?','60°=π/3 rad. La fréquence relative vaut (π/3)/(2π)=1/6 ; la fréquence réelle vaut 1200/6=200 Hz.'),
   ('Lire une décroissance','Au-delà · Temps discret','Comparer l’enveloppe rᵏ après 20 échantillons pour r=0,8 et r=0,98.','0,8²⁰≈0,01153 tandis que 0,98²⁰≈0,6676. Les deux rayons restent inférieurs à 1 ; les deux filtres sont stables, mais le second garde beaucoup plus longtemps la trace de l’impulsion.'),
   ('Choisir les zéros pour une raie','Au-delà · Traitement du signal','Pour fₑ=1000 Hz, on veut annuler 100 Hz. Quel angle ψ choisir ? Où placer les deux zéros ?','ψ=2π×100/1000=π/5=36°. Les zéros sont e±jπ/5, soit environ 0,8090±0,5878j. Ils sont conjugués et sur le cercle unité ; le filtre conserve des coefficients réels.')]),
 'modulation_am': (
  ('Le spectre du multiplicateur de P19','Spé · Physique PSI',
   '<p>Le message est cos(2πft) et la porteuse cos(2πFt), avec F&gt;f. La tension modulée est uAM=U[1+m cos(2πft)]cos(2πFt), où U est l’amplitude porteuse et m le taux de modulation. Pour un multiplicateur recevant deux tensions d’amplitudes UBF et UHF, U=Kₘ UBF UHF ; le gain Kₘ s’exprime en V⁻¹.</p><p>Le produit donne U cos(2πFt)+(mU/2)cos[2π(F+f)t]+(mU/2)cos[2π(F−f)t]. Le spectre en amplitude comporte une porteuse U et deux bandes latérales mU/2. La largeur de bande de cet exemple monochromatique vaut 2f.</p>'),
  ('Suivre l’enveloppe et conserver le signe','Spé · Physique PSI / au-delà',
   '<p>Pour 0≤m≤1, U[1+m cos(2πft)] reste positif. Une diode et un circuit RC peuvent suivre les crêtes si 1/F≪RC≪1/f. Ces repères sont approximatifs ; près de m=1, la décharge nécessaire au voisinage des minima impose un choix plus contraignant. Le détecteur simulé est idéal ; les écarts montrent l’ondulation et le suivi imparfait du message.</p><p>Pour m&gt;1, le facteur change de signe : l’enveloppe géométrique en prend la valeur absolue. Une détection d’enveloppe ne peut plus retrouver le signe. Une démodulation synchrone multiplie par une porteuse de référence puis filtre les hautes fréquences ; elle est étudiée en physique PSI.</p>'),
  [('Calculer trois amplitudes','Spé · Physique','U=2 V, m=0,6, F=2000 Hz et f=100 Hz. Donner les fréquences et les amplitudes crête des trois raies.','La porteuse est à 2000 Hz, amplitude 2 V. Les bandes latérales sont à 1900 Hz et 2100 Hz, chacune d’amplitude mU/2=0,6 V. Ces valeurs sont des amplitudes crête, pas des valeurs efficaces.'),
   ('Choisir une constante de temps','Spé · Physique','Pour F=20 kHz et f=100 Hz, proposer un RC compatible avec une détection d’enveloppe.','1/F=50 µs et 1/f=10 ms. Un RC de l’ordre de 1 ms se place entre ces deux échelles. Il faut ensuite vérifier l’ondulation et la décharge sur le signal réel : les inégalités sont des repères de choix.'),
   ('Retrouver le message par démodulation synchrone','Spé · Physique PSI','Multiplier uAM par 2 cos(2πFt), avec une référence de même phase, puis filtrer les composantes rapides. Que reste-t-il ?','2 cos²(2πFt)=1+cos(4πFt). Après passe-bas, il reste U[1+m cos(2πft)]. Retirer la composante constante U donne Um cos(2πft). Une erreur de phase de référence multiplie cette composante lente par le cosinus de l’erreur de phase.')]),
}

LESSONS=[]
EXERCISES=[]
for _lab, (_one,_two,_exercises) in _TEXTS.items():
    for _title,_level,_html in (_one,_two):
        LESSONS.append(dict(lab=_lab,title=_title,level=_level,html=_html))
    for _title,_level,_question,_answer in _exercises:
        EXERCISES.append(dict(lab=_lab,title=_title,level=_level,question=_question,answer=_answer))
